import {SITES,VIDEOS,RELAY_BV,CANTEEN_BV,CARD_STUDENT,CARD_ROWS} from './network-content.js?v=43';
const norm=v=>String(v??'').normalize('NFKC').trim().toLowerCase();
export function siteForRoute(route){const section=String(route||'#forum').slice(1).split('/')[0];return section==='portal'?'portal':['video','dynamic'].includes(section)?'video':section==='pan'?'pan':'forum';}
export function freshNetwork(){return {version:1,cardAuthorized:false,cardQuery:null,orderOpen:false,maintenanceSearch:{query:'',archived:false},complaintDraft:'',videoQuery:'',videoTimes:{},observed:[],panUnlocked:[],tableMarks:{},lastRoutes:Object.fromEntries(Object.entries(SITES).map(([id,s])=>[id,s.home]))};}
export function canViewVideo(state,id){return Object.hasOwn(VIDEOS,id)&&(id===RELAY_BV?state.finished&&state.caseStage>=1:id===CANTEEN_BV?state.caseSolved&&state.expansion.stage>=4:true);}
export function canUsePortal(state,page){return ['home','menu','complaints'].includes(page)||['card','order'].includes(page)&&state.finished||page==='timeline'&&state.caseSolved&&state.expansion.stage>=1||['ledger','workorders'].includes(page)&&state.caseSolved&&state.expansion.stage>=4;}
export function canUseShare(state,id){return id==='relay'&&canViewVideo(state,RELAY_BV)||['ledger','blackboard'].includes(id)&&canUsePortal(state,'ledger');}
export function parseNetwork(raw,state){const s=freshNetwork();if(!raw||raw.version!==1)return s;s.cardAuthorized=state.finished&&raw.cardAuthorized===true;
 if(s.cardAuthorized&&validRange(raw.cardQuery?.from,raw.cardQuery?.to))s.cardQuery={from:raw.cardQuery.from,to:raw.cardQuery.to};
 s.orderOpen=!!s.cardQuery&&raw.orderOpen===true&&CARD_ROWS.some(r=>r[0]==='C0313-2147'&&r[1].slice(0,10)>=s.cardQuery.from&&r[1].slice(0,10)<=s.cardQuery.to);
 for(const [id,time] of Object.entries(raw.videoTimes||{}))if(canViewVideo(state,id)&&Number.isFinite(time))s.videoTimes[id]=Math.max(0,Math.min(VIDEOS[id].duration,time));
 s.observed=Array.isArray(raw.observed)?[...new Set(raw.observed.filter(id=>['relayFrame','canteenFrame'].includes(id)))]:[];
 s.panUnlocked=Array.isArray(raw.panUnlocked)?[...new Set(raw.panUnlocked.filter(id=>id==='relay'&&canUseShare(state,id)))]:[];
 for(const [key,ids] of Object.entries(raw.tableMarks||{}))if(/^[a-z-]{1,30}$/.test(key)&&Array.isArray(ids))s.tableMarks[key]=[...new Set(ids.filter(id=>typeof id==='string'&&/^[\w-]{1,40}$/.test(id)))].slice(0,30);
 for(const id of Object.keys(SITES)){const route=raw.lastRoutes?.[id];if(typeof route==='string'&&route.length<180&&/^#[\w/-]+$/.test(route)&&siteForRoute(route)===id)s.lastRoutes[id]=route;}
 s.videoQuery=typeof raw.videoQuery==='string'?raw.videoQuery.slice(0,120):'';s.maintenanceSearch={query:typeof raw.maintenanceSearch?.query==='string'?raw.maintenanceSearch.query.slice(0,80):'',archived:raw.maintenanceSearch?.archived===true};s.complaintDraft=typeof raw.complaintDraft==='string'?raw.complaintDraft.slice(0,1000):'';return s;
}
export function legacyNetworkRoute(section,id){if(section==='casefile'&&id==='pickup')return '#portal/card';if(section==='casefile'&&id==='receipt')return '#portal/order';if(section==='archive'&&['roster','swipe','attendance','signoff'].includes(id))return '#portal/timeline';if(section==='archive'&&id==='ledger'||section==='vault')return '#portal/ledger';if(section==='archive'&&id==='outage')return '#portal/workorders';if(section==='archive'&&id==='blackboard')return '#pan/blackboard';return null;}
export function addressForRoute(route){const [section,id='']=String(route).slice(1).split('/');if(section==='portal')return 'canteen.qinghe.edu.cn/'+(id==='home'?'index.aspx':id+'.aspx');if(section==='video')return id?'bilibili.com/video/'+id:'bilibili.com/search';if(section==='dynamic')return 'bilibili.com/opus/'+(id||'radio');if(section==='pan')return 'pan.qinghe.local/'+(id?'s/'+id:'disk/home');return null;}
export function routeFromAddress(value){const v=String(value??'').normalize('NFKC').trim();if(/^BV[0-9a-z]{10}$/i.test(v)){const id=Object.keys(VIDEOS).find(id=>norm(id)===norm(v));return '#video/'+(id||v);}
 let url;try{url=new URL(/^[a-z]+:\/\//i.test(v)?v:'https://'+v);}catch{return null;}
 if(!['http:','https:'].includes(url.protocol)||url.username||url.password)return null;
 if(url.hostname==='canteen.qinghe.edu.cn'){const page=url.pathname.split('/').filter(Boolean)[0]?.replace(/\.aspx$/,'')||'home';return '#portal/'+(page==='index'?'home':page);}
 if(['bilibili.com','www.bilibili.com'].includes(url.hostname)){const parts=url.pathname.split('/').filter(Boolean);if(parts[0]==='video'&&parts[1])return '#video/'+parts[1];if(parts[0]==='opus')return '#dynamic/'+(parts[1]||'radio');if(['search',''].includes(parts[0]||''))return '#video';}
 if(url.hostname==='pan.qinghe.local'){const parts=url.pathname.split('/').filter(Boolean);return parts[0]==='s'&&parts[1]?'#pan/'+parts[1]:'#pan';}
 if(url.hostname==='qinghe.local'){if(url.pathname==='/thread.php'&&url.searchParams.has('id'))return '#post/'+encodeURIComponent(url.searchParams.get('id'));return '#forum';}return null;
}
export function validRange(from,to){return [from,to].every(x=>typeof x==='string'&&/^202[45]-\d{2}-\d{2}$/.test(x)&&!Number.isNaN(Date.parse(x+'T00:00:00Z'))&&new Date(x+'T00:00:00Z').toISOString().slice(0,10)===x)&&from<=to;}
export function authorizeCard(state,student,password,checkLogin){if(!state.finished||norm(student)!==CARD_STUDENT||checkLogin(state,'jiege',password).account!=='jie')return {ok:false,message:'学号或授权口令不匹配。请核对杰哥交给你的查询说明。'};state.network.cardAuthorized=true;return {ok:true,message:'已进入杰哥授权的消费查询。'};}
export function queryCard(state,from,to){if(!state.network.cardAuthorized)return {ok:false,message:'请先登录一卡通查询。'};if(!validRange(from,to))return {ok:false,message:'日期范围无效，请使用完整年月日，结束日不能早于开始日。'};state.network.cardQuery={from,to};state.network.orderOpen=false;return {ok:true,rows:CARD_ROWS.filter(r=>r[1].slice(0,10)>=from&&r[1].slice(0,10)<=to)};}
export function openCardOrder(state,id){const s=state.network;if(!s.cardAuthorized||!s.cardQuery||id!=='C0313-2147'||!CARD_ROWS.some(r=>r[0]===id&&r[1].slice(0,10)>=s.cardQuery.from&&r[1].slice(0,10)<=s.cardQuery.to))return false;s.orderOpen=true;return true;}
export function recordVideoFrame(state,id,time){if(!canViewVideo(state,id))return {ok:false,message:'这份视频尚未同步到当前存档。'};if(!Number.isFinite(time)||time<82||time>88)return {ok:false,message:'这一帧看不清场记或设备标记。可以拖动进度，暂停后再核对。'};const mark=id===RELAY_BV?'relayFrame':id===CANTEEN_BV?'canteenFrame':null;if(!mark)return {ok:false,message:'这段日常视频没有待核对的场记。'};if(!state.network.observed.includes(mark))state.network.observed.push(mark);return {ok:true,clue:id===RELAY_BV?'videoFrame':null,message:'已保存当前时刻和画面说明。弹幕中的猜测暂不作为身份结论。'};}
export function unlockShare(state,id,password){if(!canUseShare(state,id))return {ok:false,message:'这份分享暂未同步。'};if(id!=='relay')return {ok:false,message:'设备附件使用原导出包的独立解密页。'};if(norm(password)!=='1018b')return {ok:false,message:'提取码未匹配。按简介的先后顺序，核对片头日期和场记机位；不是上传日期。'};if(!state.network.panUnlocked.includes(id))state.network.panUnlocked.push(id);return {ok:true,message:'源素材目录已载入。'};}
